Nvfs_Log nvfs_log_create( NVFS_Entry_Name name  , UInt8 number_of_elements , UInt8 element_size )
{
    Nvfs_Log log = (Nvfs_Log)os_mem_request( sizeof( *log ) ) ; 

    if( log )
    {
        log->name					= name              ;         
        log->number_of_elements     = number_of_elements;        
        log->element_size			= element_size      ;     
        log->index                  = 0 				;
		
		log->buffer       =(UInt8 *)os_mem_request( (UInt16)number_of_elements * element_size ) ;     
            
        if( nvfs_rd( log->name , log->buffer ) != NVFS_OK )
        {        
            nvfs_wr_create( log->name , log->buffer , (number_of_elements*element_size)) ;                 
        }
    }
            
    return log ; 
}

